func TestOpeningASessionDropsTheAgentsFilter(t *testing.T) {
	m := withSessions(t, "/p/a.jsonl", "/p/b.jsonl")
	m, _ = opened(t, m, "right")
	m = answer(t, m, threeSubs())
	m = send(t, m, testutil.Key("/"))
